#include "gfx/shader.h"
#include "core/log.h"
#include "core/paths.h"
#include "embedded_shaders.h"   // generated by CMake from native/shaders/*.glsl
#include <vector>

namespace ag {

static GLuint compile(GLenum type, const std::string& src, const std::string& name) {
    GLuint s = glCreateShader(type);
    const char* p = src.c_str();
    glShaderSource(s, 1, &p, nullptr);
    glCompileShader(s);
    GLint ok = 0; glGetShaderiv(s, GL_COMPILE_STATUS, &ok);
    if (!ok) {
        GLint len = 0; glGetShaderiv(s, GL_INFO_LOG_LENGTH, &len);
        std::vector<char> log((size_t)len + 1);
        glGetShaderInfoLog(s, len, nullptr, log.data());
        AG_ERROR("AG: shader %s (%s) failed:\n%s", name.c_str(), type == GL_VERTEX_SHADER ? "vs" : "fs", log.data());
        glDeleteShader(s);
        return 0;
    }
    return s;
}

bool Program::build(const std::string& name, const std::string& vs, const std::string& fs) {
    name_ = name;
    GLuint v = compile(GL_VERTEX_SHADER, vs, name), f = compile(GL_FRAGMENT_SHADER, fs, name);
    if (!v || !f) { if (v) glDeleteShader(v); if (f) glDeleteShader(f); return false; }
    GLuint p = glCreateProgram();
    glAttachShader(p, v); glAttachShader(p, f);
    glLinkProgram(p);
    glDeleteShader(v); glDeleteShader(f);
    GLint ok = 0; glGetProgramiv(p, GL_LINK_STATUS, &ok);
    if (!ok) {
        GLint len = 0; glGetProgramiv(p, GL_INFO_LOG_LENGTH, &len);
        std::vector<char> log((size_t)len + 1);
        glGetProgramInfoLog(p, len, nullptr, log.data());
        AG_ERROR("AG: program %s link failed:\n%s", name.c_str(), log.data());
        glDeleteProgram(p);
        return false;
    }
    destroy();
    id_ = p;
    locs_.clear();
    return true;
}

void Program::destroy() { if (id_) glDeleteProgram(id_); id_ = 0; locs_.clear(); }
void Program::use() const { glUseProgram(id_); }

GLint Program::loc(const char* n) {
    auto it = locs_.find(n);
    if (it != locs_.end()) return it->second;
    GLint l = glGetUniformLocation(id_, n);
    locs_.emplace(n, l);
    return l;
}
void Program::set(const char* n, int v) { GLint l = loc(n); if (l >= 0) glUniform1i(l, v); }
void Program::set(const char* n, float v) { GLint l = loc(n); if (l >= 0) glUniform1f(l, v); }
void Program::set(const char* n, const V2& v) { GLint l = loc(n); if (l >= 0) glUniform2f(l, v.x, v.y); }
void Program::set(const char* n, const V3& v) { GLint l = loc(n); if (l >= 0) glUniform3f(l, v.x, v.y, v.z); }
void Program::set(const char* n, const V4& v) { GLint l = loc(n); if (l >= 0) glUniform4f(l, v.x, v.y, v.z, v.w); }
void Program::set(const char* n, const M4& m) { GLint l = loc(n); if (l >= 0) glUniformMatrix4fv(l, 1, GL_FALSE, m.m); }
void Program::setArray(const char* n, const V3* v, int count) { GLint l = loc(n); if (l >= 0 && count > 0) glUniform3fv(l, count, &v[0].x); }
void Program::setArray(const char* n, const float* v, int count) { GLint l = loc(n); if (l >= 0 && count > 0) glUniform1fv(l, count, v); }
void Program::sampler(const char* n, int unit, GLuint tex, GLenum target) {
    glActiveTexture(GL_TEXTURE0 + unit);
    glBindTexture(target, tex);
    GLint l = loc(n);
    if (l >= 0) glUniform1i(l, unit);
}

std::string shaderSource(const std::string& file) {
    // dev hot-reload: a shaders/ folder next to the assets wins over the embedded copy
    std::string dev = paths::join(paths::dirname(paths::assetRoot()), "shaders/" + file);
    if (paths::exists(dev)) { std::string t = paths::readText(dev); if (!t.empty()) return t; }
    for (int i = 0; i < kEmbeddedShaderCount; ++i)
        if (file == kEmbeddedShaders[i].name) return kEmbeddedShaders[i].source;
    AG_ERROR("AG: missing shader %s", file.c_str());
    return {};
}

namespace gl {
void restoreRaylibState(int w, int h) {
    glBindFramebuffer(GL_FRAMEBUFFER, 0);
    glViewport(0, 0, w, h);
    glUseProgram(0);
    glBindVertexArray(0);
    glDisable(GL_DEPTH_TEST);
    glDepthMask(GL_TRUE);
    glDepthFunc(GL_LEQUAL);
    glEnable(GL_CULL_FACE);
    glCullFace(GL_BACK);
    glFrontFace(GL_CCW);
    glEnable(GL_BLEND);
    glBlendEquation(GL_FUNC_ADD);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    glColorMask(GL_TRUE, GL_TRUE, GL_TRUE, GL_TRUE);
    glActiveTexture(GL_TEXTURE0);
}
}  // namespace gl

}  // namespace ag
